data: {"id":"chatcmpl-20261013155950818464406c955d568WH6hsuyR","created":1791907191,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_f40898abd0bf4866abd1caa8","index":1,"type":"function","function":{"name":"write","arguments":"{\"content\":\"import os\\nimport re\\nimport sys\\n\\nAXIOMS = [\\\"A1\\\", \\\"A2\\\", \\\"A3\\\", \\\"A4\\\"]\\nCONVS = [f\\\"C{i}\\\" for i in range(1, 7)]\\nLEMMAS = [\\\"L1\\\", \\\"L2\\\"]\\nALLOWED = set(AXIOMS) | set(CONVS) | set(LEMMAS)\\n\\n\\ndef section(text, start, end_markers):\\n    i = text.find(start)\\n    if i == -1:\\n        return \\\"\\\"\\n    j = len(text)\\n    for em in end_markers:\\n        k = text.find(em, i + len(start))\\n        if k != -1:\\n            j = min(j, k)\\n    return text[i:j]\\n\\n\\ndef extract_citations(chunk):\\n    toks = []\\n    for br in re.findall(r\\\"\\\\[([^\\\\]]*)\\\\]\\\", chunk):\\n        for part in re.split(r\\\"[;,]| and \\\", br):\\n            part = part.strip()\\n            if not part:\\n                continue\\n            first = part.split()[0].strip(\\\".,:;\\\")\\n            for tok in first.split(\\\"/\\\"):\\n                tok = tok.strip()\\n                if re.fullmatch(r\\\"[ACL]\\\\d+\\\", tok):\\n                    toks.append(tok)\\n    return toks\\n\\n\\ndef main():\\n    base = os.path.dirname(os.path.abspath(__file__))\\n    with open(os.path.join(base, \\\"proof.txt\\\")) as f:\\n        text = f.read()\\n\\n    checks = []\\n\\n    axioms_sec = section(text, \\\"Axioms\\\", [\\\"Conventions\\\"])\\n    conv_sec = section(text, \\\"Conventions\\\", [\\\"Derived lemmas\\\"])\\n    lem_sec = section(text, \\\"Derived lemmas\\\", [\\\"Main derivation\\\"])\\n    deriv_sec = section(text, \\\"Main derivation\\\", [\\\"Since x was arbitrary\\\"])\\n\\n    declared_axioms = {\\\"A\\\" + m for m in re.findall(r\\\"^A(\\\\d+)\\\\s*\\\\(\\\", axioms_sec, re.M)}\\n    checks.append(\\n        (\\\"declared axioms are exactly A1-A4\\\",\\n         \\\"PASS\\\" if declared_axioms == set(AXIOMS) else \\\"FAIL\\\",\\n         \\\"declared: \\\" + (\\\", \\\".join(sorted(declared_axioms)) or \\\"none\\\")),\\n    )\\n\\n    declared_convs = {\\\"C\\\" + m for m in re.findall(r\\\"^C(\\\\d+)\\\\s\\\", conv_sec, re.M)}\\n    checks.append(\\n        (\\\"declared conventions are exactly C1-C6\\\",\\n         \\\"PASS\\\" if declared_convs == set(CONVS) else \\\"FAIL\\\",\\n         \\\"declared: \\\" + (\\\", \\\".join(sorted(declared_convs)) or \\\"none\\\")),\\n    )\\n\\n    l1 = lem_sec.find(\\\"L1 (\\\")\\n    l2 = lem_sec.find(\\\"L2 (\\\")\\n    base_ids = set(AXIOMS) | set(CONVS)\\n    if l1 != -1 and l2 != -1 and l1 < l2:\\n        l1c = set(extract_citations(lem_sec[l1:l2]))\\n        l2c = set(extract_citations(lem_sec[l2:]))\\n        checks.append(\\n            (\\\"lemma L1 derived only from axioms/conventions\\\",\\n             \\\"PASS\\\" if l1c <= base_ids else \\\"FAIL\\\",\\n             \\\"cites: \\\" + \\\", \\\".join(sorted(l1c))),\\n        )\\n        checks.append(\\n            (\\\"lemma L2 derived only from axioms/conventions\\\",\\n             \\\"PASS\\\" if l2c <= base_ids else \\\"FAIL\\\",\\n             \\\"cites: \\\" + \\\", \\\".join(sorted(l2c))),\\n        )\\n    else:\\n        checks.append((\\\"lemma sections found\\\", \\\"FAIL\\\", \\\"L1/L2 blocks missing or out of order\\\"))\\n        l1c, l2c = set(), set()\\n\\n    steps = re.findall(r\\\"^\\\\s*(\\\\d+)\\\\.\\\\s+(.*)$\\\", deriv_sec, re.M)\\n    step_errors = []\\n    cited = set()\\n    for num, body in steps:\\n        if num == \\\"1\\\":\\n            if \\\"=\\\" in body or \\\"[\\\" in body:\\n                step_errors.append(f\\\"step 1 should be the bare LHS term: {body.strip()[:50]}\\\")\\n            continue\\n        if \\\"=\\\" not in body:\\n            step_errors.append(f\\\"step {num} has no '='\\\")\\n        c = extract_citations(body)\\n        if not c:\\n            step_errors.append(f\\\"step {num} lacks a citation\\\")\\n        for t in c:\\n            if t not in ALLOWED:\\n                step_errors.append(f\\\"step {num} cites unknown rule {t}\\\")\\n            cited.add(t)\\n    checks.append(\\n        (\\\"derivation steps well-formed, citing only allowed rules\\\",\\n         \\\"PASS\\\" if not step_errors else \\\"FAIL\\\",\\n         f\\\"{len(steps)} steps checked\\\" + (\\\"\\\" if not step_errors else \\\"; \\\" + \\\"; \\\".join(step_errors))),\\n    )\\n\\n    used_axioms = cited | l1c | l2c\\n    missing = [a for a in AXIOMS if a not in used_axioms]\\n    checks.append(\\n        (\\\"all four permitted axioms are used\\\",\\n         \\\"PASS\\\" if not missing else \\\"FAIL\\\",\\n         \\\"unused: \\\" + \\\", \\\".join(missing) if missing else \\\"A1-A4 all cited\\\"),\\n    )\\n\\n    fin = re.search(r\\\"forall x : Int\\\\. \\\\(x \\\\+ 1\\\\) \\\\* \\\\(x - 1\\\\) = x\\\\^2 - 1\\\", text) and \\\"QED\\\" in text\\n    checks.append((\\\"final goal statement and QED present\\\", \\\"PASS\\\" if fin else \\\"FAIL\\\", \\\"\\\"))\\n\\n    bad = [x for x in range(-100000, 100001) if (x + 1) * (x - 1) != x * x - 1]\\n    checks.append(\\n        (\\\"numeric agreement for 200001 integers in [-100000, 100000]\\\",\\n         \\\"PASS\\\" if not bad else \\\"FAIL\\\",\\n         \\\"no mismatch\\\" if not bad else f\\\"mismatches at x={bad[:5]}\\\"),\\n    )\\n\\n    big = [10**40 + 7, -(10**40 + 7), 2**100 + 3, -(2**100 + 3)]\\n    bigbad = [v for v in big if (v + 1) * (v - 1) != v * v - 1]\\n    checks.append(\\n        (\\\"numeric agreement for extreme magnitudes (|x| up to ~1e30)\\\",\\n         \\\"PASS\\\" if not bigbad else \\\"FAIL\\\",\\n         f\\\"{len(big)} values tested\\\" if not bigbad else f\\\"mismatch at {bigbad}\\\"),\\n    )\\n\\n    try:\\n        import sympy\\n\\n        xs = sympy.symbols(\\\"x\\\")\\n        sym = sympy.expand((xs + 1) * (xs - 1) - (xs**2 - 1)) == 0\\n        checks.append((\\\"symbolic identity via sympy expand\\\", \\\"PASS\\\" if sym else \\\"FAIL\\\", \\\"sympy \\\" + sympy.__version__))\\n    except ImportError:\\n        checks.append((\\\"symbolic identity via sympy expand\\\", \\\"SKIPPED\\\", \\\"sympy not installed\\\"))\\n\\n    print(\\\"checker.py - validation report for proof.txt\\\")\\n    print(\\\"claim: forall x : Int. (x + 1) * (x - 1) = x^2 - 1\\\")\\n    print(\\\"allowed axioms: \\\" + \\\", \\\".join(AXIOMS))\\n    print()\\n    for i, (name, status, detail) in enumerate(checks, 1):\\n        line = f\\\"CHECK {i}: {name} -> {status}\\\"\\n        if detail:\\n            line += f\\\" ({detail})\\\"\\n        print(line)\\n    npass = sum(1 for c in checks if c[1] == \\\"PASS\\\")\\n    nfail = sum(1 for c in checks if c[1] == \\\"FAIL\\\")\\n    nskip = sum(1 for c in checks if c[1] == \\\"SKIPPED\\\")\\n    print()\\n    print(f\\\"OVERALL: {'PASS' if nfail == 0 else 'FAIL'} ({npass} passed, {nfail} failed, {nskip} skipped)\\\")\\n    sys.exit(0 if nfail == 0 else 1)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"filePath\":\"/home/agent/workspace/checker.py\"}"}}]}}]}

